import {SAMPLE_PRESETS,samplePreset} from './sampler-core.js';
const legacyCategory={keys:'Recorded keys',pluck:'Recorded strings',bass:'Recorded bass',lead:'Recorded winds and strings',pad:'Recorded strings',kick:'Recorded drums',snare:'Recorded drums',hat:'Recorded drums'};
const featured=['karoryfer-guitar','vsco-violin','vsco-clarinet','vsco-piano-full','vsco-bass','vsco-flute','vsco-cello','vsco-harp','sonic-kick','sonic-snare','sonic-hat','fluid-004','fluid-016','fluid-056','fluid-065','fluid-052','fluid-053','edm-bass-3','edm-lead-1','edm-pad-1','edm-pluck-2','edm-kick-3','edm-snare-2','edm-hat-1'];
export function soundOriginLabel(id){const p=samplePreset(id);return p.source==='fluid'?'FluidR3 soundbank · MIT':p.source==='sprout-dsp'?'Original synthesis · CC0':p.source==='karoryfer'?'Karoryfer recording · CC0':p.source==='sonic'?'Sonic Pi recording · CC0':'VSCO recording · CC0'}
export function soundEntry(id){const p=samplePreset(id);return {id,name:p.name,label:p.label,instrument:p.instrument,kind:p.kind,category:p.category??legacyCategory[p.instrument],origin:p.origin??'recording',sourceLabel:soundOriginLabel(id),description:p.description,featured:featured.includes(id)}}
const entries=Object.keys(SAMPLE_PRESETS).map(soundEntry),families=[...new Set(entries.map(p=>p.category))].sort();
export function soundCatalogFilters(){return [{id:'featured',name:'Featured'},{id:'all',name:'All sounds'},{id:'recording',name:'Acoustic recordings'},{id:'soundfont',name:'General MIDI soundbank'},{id:'edm',name:'EDM synthesized patches'},...families.map(name=>({id:'family:'+name,name}))]}
export function querySounds({query='',category='all',instrument,limit=24}={}){
 if(typeof query!=='string'||query.length>120||!soundCatalogFilters().some(c=>c.id===category)||instrument!==undefined&&!['kick','snare','hat','bass','keys','lead','pad','pluck'].includes(instrument)||!Number.isInteger(limit)||limit<1||limit>256)throw Error('Invalid sound library filter');
 const terms=query.normalize('NFKC').toLocaleLowerCase('en').trim().split(/\s+/).filter(Boolean),list=entries.filter(e=>(instrument===undefined||e.instrument===instrument)&&(category==='all'||category==='featured'&&e.featured||category==='edm'&&e.origin==='synthesized'||category===e.origin||category==='family:'+e.category)&&terms.every(term=>[e.id,e.name,e.label,e.category,e.instrument,e.origin,e.description,e.sourceLabel].join(' ').normalize('NFKC').toLocaleLowerCase('en').includes(term)));
 if(category==='featured')list.sort((a,b)=>featured.indexOf(a.id)-featured.indexOf(b.id));return {total:list.length,catalogTotal:entries.length,entries:list.slice(0,limit).map(e=>({...e})),hasMore:list.length>limit};
}
export function sourceGroups(instrument){const groups=new Map();for(const e of querySounds({instrument,limit:256}).entries){if(!groups.has(e.category))groups.set(e.category,[]);groups.get(e.category).push(e)}return [...groups].map(([name,sounds])=>({name,sounds}))}
export function catalogSummary(){return {total:entries.length,recordings:entries.filter(e=>e.origin==='recording').length,soundbank:entries.filter(e=>e.origin==='soundfont').length,synthesized:entries.filter(e=>e.origin==='synthesized').length,categories:families.length,files:new Set(Object.values(SAMPLE_PRESETS).flatMap(p=>p.assets)).size}}
